import { resourceServerProjectionToValue } from './resource-server.model';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import {
  InteractionMocks,
  RepositoryMock,
  allow,
  configureFeatureTesting,
  createWithoutTemplate,
  internals,
  mockRepository,
  mockTick,
  moduleCompiles,
} from 'app/shared/testing/feature-testing';

describe('resourceServerProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    code: 'value-code',
    apiKey: 'value-apiKey',
    enabled: 'value-enabled',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(resourceServerProjectionToValue(null)).toBeNull();
    expect(resourceServerProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(resourceServerProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      code: 'value-code',
      apiKey: 'value-apiKey',
      enabled: 'value-enabled',
      version: 'value-version',
    } as any;
    expect(resourceServerProjectionToValue(projection)).toEqual(value);
  });
});
